import type {Locale} from '../../src/core/types';
import type {StoryFact} from '../../src/core/story-update';
import {roleSeed} from '../../src/core/story-role-binding';
import {DEFAULT_ACTIONS} from '../../src/core/characters';
import {admissionWorld} from './story-topic-admission';

const settings=[
 {id:'repair',ru:['красные ворота','починить','восстановить','ремонтирую'],en:['red gate','repair','mend','am repairing']},
 {id:'return',ru:['синий альбом','вернуть','возвратить','возвращаю'],en:['blue album','return','give back','am returning']},
 {id:'delivery',ru:['медицинский набор','доставить','принести','доставляю'],en:['medical kit','deliver','bring','am delivering']},
] as const;
/** Independent expected tasks and source prose, never generated by the scorer. */
export function taskGoalWorld(locale:Locale,setting:typeof settings[number]=settings[0]!) {
 const f=admissionWorld(locale),[object,verb,alias,action]=setting[locale],N=f.base.entities[0]!,M=f.base.entities[1]!;
 for(const person of f.base.entities)person.characterSheet!.protagonist=false;
 const first=f.s(`Нора обещала Мире ${alias} ${object} только после разрешения охраны.`,`Nora promised Mira to ${alias} the ${object} only after the guards give permission.`);
 const last=f.s(`Мира планирует ${verb} ${object}, если Нора согласится; согласие пока не получено.`,`Mira plans to ${verb} the ${object} if Nora agrees; agreement has not been obtained.`);
 const oldest:StoryFact={kind:'promise',text:first,quote:first,task:{key:'first-goal-duty',title:f.s(`${alias} ${object}`,`${alias} the ${object}`),status:'open'}};
 const newest:StoryFact={kind:'plan',text:last,quote:last,task:{key:'last-goal-duty',title:f.s(`${verb} ${object}`,`${verb} the ${object}`),status:'open'}};
 const extras:StoryFact[]=Array.from({length:100},(_,i)=>{const text=f.s(`Нора обещала Мире обсудить, как ${verb} ${object}. Беседа ${i}.`,`Nora promised Mira to discuss how to ${verb} the ${object}. Conversation ${i}.`);return {kind:'promise',text,quote:text,task:{key:'discussion-'+i,title:f.s(`Обсудить, как ${verb} ${object}. Беседа ${i}.`,`Discuss how to ${verb} the ${object}. Conversation ${i}.`),status:'open'}};});
 const noise:StoryFact[]=Array.from({length:20},(_,i)=>{const text=f.s(`Нора и Мира обсуждали, как ${verb} ${object}. Разговор ${i}.`,`Nora and Mira discussed how to ${verb} the ${object}. Talk ${i}.`);return {kind:'event',text,quote:text};});
 const latest=noise.at(-1)!,sources=['first-goal-source','last-goal-source',...extras.map((_,i)=>'discussion-'+i),...noise.map((_,i)=>'later-scene-'+i)];
 const seed=(fact:StoryFact,source:string,role:'promisor'|'planner'|'speaker',person:typeof N)=>roleSeed(fact,{version:1,sourceRevisionId:source,quote:fact.quote,roles:{[role]:{id:person.id,name:person.name}}});
 const seeds=[seed(oldest,sources[0]!,'promisor',N),seed(newest,sources[1]!,'planner',M),...extras.map((fact,i)=>seed(fact,sources[i+2]!,'promisor',N)),...noise.map((fact,i)=>roleSeed(fact,{version:1,sourceRevisionId:sources[102+i]!,quote:fact.quote,roles:{}}))];
 const input=f.input;input.story!.facts=[oldest,newest,...extras,...noise];input.story!.episodeSources=sources;input.story!.roleSeeds=seeds;input.recentMessages=[latest.text];
 input.character=[f.base.world.id,f.base.binding.chatId,f.base.entities,f.base.binding.characterScenes![f.base.world.id],DEFAULT_ACTIONS,[],latest.text,'goal-request',true,false,false];
 input.draft=f.s(`Моя цель — ${verb} ${object}.`,`My goal is to ${verb} the ${object}.`);
 return {...f,input,oldest,newest,extras,noise,latest,sources,seeds,seed,object,verb,action};
}
export function taskGoalQualityCorpus(locale:Locale) {
 const positives=settings.flatMap(setting=>['goal','continue-goal','action','tight-budget'].map(id=>{
  const f=taskGoalWorld(locale,setting),input=f.input;
  if(id==='continue-goal')input.draft=f.s(`Продолжай: ${f.verb} ${f.object}.`,`Continue: ${f.verb} the ${f.object}.`);
  if(id==='action')input.draft=f.s(`Я ${f.action} ${f.object}.`,`I ${f.action} the ${f.object}.`);
  if(id==='tight-budget')input.settings.contextBudget=2000;
  return {name:setting.id+':'+locale+':'+id,input,wanted:[f.latest,f.oldest,f.newest],balance:true};
 }));
 const controls=['plain','topic','owner','quoted','negated','compound','personal-object','one-task','unknown-roles','empty-scene','foreign-scope','required-overflow'] as const;
 return [...positives,...controls.map(id=>{
  const f=taskGoalWorld(locale),input=f.input;
  if(id==='plain')input.draft=f.s('Продолжай.','Continue.');
  if(id==='topic')input.draft=f.s('Напомни о красных воротах.','Remind me about the red gate.');
  if(id==='owner')input.draft=f.s('Что Нора обещала Мире?','What did Nora promise Mira?');
  if(id==='quoted')input.draft=f.s('«Моя цель — починить красные ворота».','"My goal is to repair the red gate".');
  if(id==='negated')input.draft=f.s('Моя цель — не починить красные ворота.','My goal is not to repair the red gate.');
  if(id==='compound')input.draft=f.s('Моя цель — починить красные ворота и уйти.','My goal is to repair the red gate and leave.');
  if(id==='personal-object')input.draft=f.s('Моя цель — починить её ворота.','My goal is to repair her gate.');
  if(id==='one-task')input.story!.facts=input.story!.facts.filter(fact=>fact!==f.newest);
  if(id==='unknown-roles')input.story!.roleSeeds=[];
  if(id==='empty-scene')input.character![3]!.presentIds=[];
  if(id==='foreign-scope'){input.entities=input.entities!.map(e=>({...e,worldId:'elsewhere'}));input.character![2]=input.entities;}
  if(id==='required-overflow'){input.settings.contextBudget=500;input.requiredContext='ENTIRE AUTHOR RULE. '.repeat(200);}
  return {name:'control:'+locale+':'+id,input,wanted:[],balance:false};
 })];
}
